-- Verify: counts by new due date (dated rows) and parked rows tagged by this triage
select coalesce(next_step_due::text,'(parked, no date)') as new_due, ball_with, count(*) from fs_partners where notes like '%[2026-11-20 triage]%' group by 1,2 order by 1,2;
-- Remaining in-scope stale rows (expected 25 = needs-Stephen list; 0 more after Stephen decides)
select count(*) as still_stale from fs_partners where next_step_due < '2026-11-20' and ball_with not in ('parked','cpd_hold') and stage not in ('declined','not_qualified','on_hold');

